const input = $input.first().json;
const listings = input.listings || [];
const newCount = input.newCount || 0;
const activeCount = input.activeCount || 0;
const timestamp = input.timestamp || new Date().toISOString();
const date = timestamp.split('T')[0];

if (listings.length === 0) {
  return [{ json: { skip: true } }];
}

// Build header
let text = `\u{1F3E0} *${newCount} new apartment(s) found!*\n`;
text += `\u{1F4C5} ${date} | \u{1F4CA} ${activeCount} active total\n`;
text += `\u{2500}\u{2500}\u{2500}\u{2500}\u{2500}\u{2500}\u{2500}\u{2500}\u{2500}\u{2500}\u{2500}\u{2500}\u{2500}\u{2500}\u{2500}\u{2500}\u{2500}\u{2500}\u{2500}\u{2500}\n\n`;

const messages = [];

// Format each listing (batch into messages of max 5)
for (let i = 0; i < listings.length; i++) {
  const l = listings[i];
  const price = l.price ? Number(l.price).toLocaleString('lt-LT') : '?';
  const area = l.area || '?';
  const rooms = l.rooms || '?';
  const floor = l.floor || '?';

  let entry = `*${i + 1}. ${l.address}*\n`;
  entry += `\u{1F4B0} ${price} \u{20AC} | \u{1F4CF} ${area} m\u{00B2} | \u{1F6CF} ${rooms} rooms | \u{1F3E2} Floor: ${floor}\n`;

  if (l.description) {
    const desc = l.description.substring(0, 200);
    entry += `\u{1F4DD} ${desc}${l.description.length > 200 ? '...' : ''}\n`;
  }
  if (l.agentName) {
    entry += `\u{1F464} ${l.agentName}`;
    if (l.agentPhone) entry += ` | \u{1F4DE} ${l.agentPhone}`;
    entry += '\n';
  }
  entry += `\u{1F517} [View listing](${l.url})\n\n`;

  text += entry;

  // Telegram message limit ~4096 chars. Split at ~3500 to be safe.
  if (text.length > 3500 || i === listings.length - 1) {
    messages.push({ json: { text, skip: false } });
    text = '';
  }
}

return messages;
